273	###############################################################################
274	## Sets an interface structure by the specified options.
275	## The returned structure can be used to generate the actual interface in the
276	## specified output folder with 'ipl::generate_interface' procedure.
277	## Quick usage: 'ipl::generate_interface [ipl::create_interface <options>] ./'
278	#
279	# \opt[if] -if $if
280	# \opt[vlnv] -vlnv {analog.com:<lib_name>:<interface_name>:<interface_version>}
281	# \opt[directConnection] -directConnection true
282	# \opt[isAddressable] -isAddressable false
283	# \opt[description] -description "description of the interface"
284	# \opt[ports] -ports {{-n DATA -d <in/out> -p <required/optional> -w 16}
285	#                     {-n CLK -d <in/out> -p <required/optional> -w 1}}
286	#            NOTE: -n means logicalName if the port
287	#                  -d means direction
288	#                  -p means presence
289	#                  -w means width (use it only when you want to force the width)
290	###############################################################################
291	    proc create_interface {args} {
292	        array set opt [list -if "$::ipl::if" \
293	            -vlnv "" \
294	            -vendor "" \
295	            -library "" \
296	            -name "" \
297	            -version "" \
298	            -directConnection "" \
299	            -isAddressable "" \
300	            -description "" \
301	            -ports ""  \
302	        {*}$args]
303	
304	        set if $opt(-if)
305	        set ports $opt(-ports)
306	        set vlnv $opt(-vlnv)
307	
308	        set vlnv [split $vlnv ":"]
309	        set ll [llength $vlnv]
310	        if {$ll == 4} {
311	            set vendor [lindex $vlnv 0]
312	            set library [lindex $vlnv 1]
313	            set name [lindex $vlnv 2]
314	            set version [lindex $vlnv 3]
315	            set opt(-vendor) [lindex $vlnv 0]
316	            set opt(-library) [lindex $vlnv 1]
317	            set opt(-name) [lindex $vlnv 2]
318	            set opt(-version) [lindex $vlnv 3]
319	        } else {
320	            puts {WARNING: vlnv is not correct!}
321	        }
322	
323	        set optla {
324	            vendor
325	            library
326	            name
327	            version
328	            description
329	        }
330	        set optlb {
331	            vendor
332	            library
333	            name
334	            version
335	            directConnection
336	            isAddressable
337	            description
338	        }
339	
340	        if {[ipl::getnchilds {} abstractionDefinition_desc $if] == ""} {
341	            set abst $::ipl::abstractionDefinition_desc
342	            set if [ipl::setnode {} abstractionDefinition_desc $abst $if]
343	        }
344	        if {[ipl::getnchilds {} busDefinition_desc $if] == ""} {
345	            set busd $::ipl::busDefinition_desc
346	            set if [ipl::setnode {} busDefinition_desc $busd $if]
347	        }
348	
349	        set atts [list library "library=\"$library\"" \
350	            name "name=\"$name\"" \
351	            vendor "vendor=\"$vendor\"" \
352	            version "version=\"$version\""]
353	        set if [ipl::setatts abstractionDefinition_desc \
354	            ipxact:busType $atts $if]
355	
356	        foreach op $optla {
357	            set val $opt(-$op)
358	            if {$val != ""} {
359	                set gtnm [ipl::getnname abstractionDefinition_desc \
360	                    "ipxact:$op" $if]
361	                if {$gtnm != ""} {
362	                    set if [ipl::setncont abstractionDefinition_desc \
363	                        "ipxact:$op" $val $if]
364	                } else {
365	                    set if [ipl::setnode abstractionDefinition_desc \
366	                        "ipxact:$op" [list "ipxact:$op" {} $val {}] $if]
367	                }
368	            }
369	        }
370	        foreach op $optlb {
371	            set val $opt(-$op)
372	            if {$val != ""} {
373	                if {[ipl::getnname busDefinition_desc "ipxact:$op" $if] != ""} {
374	                    set if [ipl::setncont busDefinition_desc \
375	                        "ipxact:$op" $val $if]
376	                } else {
377	                    set if [ipl::setnode busDefinition_desc \
378	                        "ipxact:$op" [list "ipxact:$op" {} $val {}] $if]
379	                }
380	            }
381	        }
382	        set if [ipl::add_interface_ports $if $ports]
383	        return $if
384	    }
