386	    proc add_interface_port {args} {
387	        array set opt [list -if "$::ipl::if" \
388	            -logicalName "" \
389	            -description "" \
390	            -qualifier "data" \
391	            -presence "" \
392	            -width "" \
393	            -direction "" \
394	        {*}$args]
395	
396	        set if $opt(-if)
397	        set logicalName $opt(-logicalName)
398	        set description $opt(-description)
399	        set qualifier $opt(-qualifier)
400	        set presence $opt(-presence)
401	        set width $opt(-width)
402	        set direction $opt(-direction)
403	        set port $::ipl::port_desc
404	
405	        if {$logicalName != ""} {
406	            set port [ipl::setncont {} ipxact:logicalName $logicalName $port]
407	        }
408	        if {$description != ""} {
409	            set port [ipl::setncont {} ipxact:description $description $port]
410	        } else {
411	            set port \
412	                [ipl::setncont {} ipxact:description "$logicalName port" $port]
413	        }
414	
415	        switch $qualifier {
416	            clock {
417	                set port [ipl::setnname ipxact:wire/ipxact:qualifier \
418	                    ipxact:isClock ipxact:isClock $port]
419	                set port [ipl::setncont ipxact:wire/ipxact:qualifier \
420	                    ipxact:isClock true $port]
421	            }
422	            reset {
423	                set port [ipl::setnname ipxact:wire/ipxact:qualifier \
424	                    ipxact:isReset ipxact:isReset $port]
425	                set port [ipl::setncont ipxact:wire/ipxact:qualifier \
426	                    ipxact:isReset true $port]
427	            }
428	            data {
429	                set port [ipl::setnname ipxact:wire/ipxact:qualifier \
430	                    ipxact:isData ipxact:isData $port]
431	                set port [ipl::setncont ipxact:wire/ipxact:qualifier \
432	                    ipxact:isData true $port]
433	            }
434	            address {
435	                set port [ipl::setnname ipxact:wire/ipxact:qualifier \
436	                    ipxact:isAddress ipxact:isAddress $port]
437	                set port [ipl::setncont ipxact:wire/ipxact:qualifier \
438	                    ipxact:isAddress true $port]
439	            }
440	            add {
441	                set port [ipl::setnname ipxact:wire/ipxact:qualifier \
442	                    ipxact:isAddress ipxact:isAddress $port]
443	                set port [ipl::setncont ipxact:wire/ipxact:qualifier \
444	                    ipxact:isAddress true $port]
445	            }
446	        }
447	        if {$presence != ""} {
448	            set port [ipl::setncont \
449	                ipxact:wire/ipxact:onMaster ipxact:presence $presence $port]
450	            set port [ipl::setncont \
451	                ipxact:wire/ipxact:onSlave ipxact:presence $presence $port]
452	        }
453	        if {$width != ""} {
454	            set port [ipl::setnname \
455	                ipxact:wire/ipxact:onMaster ipxact:width ipxact:width $port]
456	            set port [ipl::setnname \
457	                ipxact:wire/ipxact:onSlave ipxact:width ipxact:width $port]
458	            set port [ipl::setncont \
459	                ipxact:wire/ipxact:onMaster ipxact:width $width $port]
460	            set port [ipl::setncont \
461	                ipxact:wire/ipxact:onSlave ipxact:width $width $port]
462	        }
463	        if {$direction != ""} {
464	            if {$direction == "in"} {
465	                set port [ipl::setncont \
466	                    ipxact:wire/ipxact:onMaster ipxact:direction in $port]
467	                set port [ipl::setncont \
468	                    ipxact:wire/ipxact:onSlave ipxact:direction out $port]
469	            }
470	            if {$direction == "out"} {
471	                set port [ipl::setncont \
472	                    ipxact:wire/ipxact:onMaster ipxact:direction out $port]
473	                set port [ipl::setncont \
474	                    ipxact:wire/ipxact:onSlave ipxact:direction in $port]
475	            }
476	        }
477	        if {$qualifier == "clock" || $qualifier == "reset"} {
478	            set port [ipl::setncont \
479	                ipxact:wire/ipxact:onMaster ipxact:direction in $port]
480	            set port [ipl::setncont \
481	                ipxact:wire/ipxact:onSlave ipxact:direction in $port]
482	            set port [ipl::setnname \
483	                ipxact:wire ipxact:requiresDriver ipxact:requiresDriver $port]
484	            switch $qualifier {
485	                clock {
486	                    set port [ipl::setatt ipxact:wire ipxact:requiresDriver \
487	                        driverType "driverType=\"clock\"" $port]
488	                }
489	                reset {
490	                    set port [ipl::setatt ipxact:wire ipxact:requiresDriver \
491	                        driverType "driverType=\"singleShot\"" $port]
492	                }
493	            }
494	            set port \
495	                [ipl::setncont ipxact:wire ipxact:requiresDriver true $port]
496	        }
497	        if {[ipl::getnchilds {} abstractionDefinition_desc $if] == ""} {
498	            set abst $::ipl::abstractionDefinition_desc
499	            set if [ipl::setnode {} abstractionDefinition_desc $abst $if]
500	        }
501	
502	        set if [ipl::setnode abstractionDefinition_desc/ipxact:ports \
503	            $logicalName $port $if]
504	
505	        return $if
506	    }
507	
508	    proc add_interface_ports {if ports} {
509	        foreach port $ports {
510	            set opts {}
511	            if {[dict keys $port -n] != ""} {
512	                dict set opts -logicalName [dict get $port -n]
513	            }
514	            if {[dict keys $port -d] != ""} {
515	                dict set opts -direction [dict get $port -d]
516	            }
517	            if {[dict keys $port -w] != ""} {
518	                dict set opts -width [dict get $port -w]
519	            }
520	            if {[dict keys $port -q] != ""} {
521	                dict set opts -qualifier [dict get $port -q]
522	            }
523	            if {[dict keys $port -p] != ""} {
524	                dict set opts -presence [dict get $port -p]
525	            }
526	            set if [ipl::add_interface_port -if $if {*}$opts]
527	        }
528	        return $if
529	    }
