531	###############################################################################
532	## Generates an interface by the input interface structure and a given path.
533	## Quick usage: 'ipl::generate_interface [ipl::create_interface <options>] ./'
534	#               or 'set if [ipl::create_interface <options>]'
535	#                  'ipl::generate_interface $if ./'
536	#
537	# \parameter[if] $if
538	# \parameter[dpath] ./ (if no path is given it generates the interface in the
539	#                       default interface directory of Propel Builder IP
540	#                       download directory which is included in Propel Builder
541	#                       in default)
542	###############################################################################
543	    proc generate_interface {if {dpath ""}} {
544	        if {$dpath == ""} {
545	            if {[info exists ::env(LATTICE_DEFAULT_PATHS)] && \
546	                $::env(LATTICE_DEFAULT_PATHS) == 1} {
547	                set dpaths [list ./ltt $ipl::PropelIPLocal_path/interfaces]
548	            } else {
549	                set dpaths ./ltt
550	            }
551	            foreach dp $dpaths {
552	                generate_interface_on_path $if $dp
553	            }
554	        } else {
555	            generate_interface_on_path $if $dpath
556	        }
557	    }
558	
559	    proc generate_interface_on_path {if {dpath ""}} {
560	        if {$dpath == ""} {
561	            set dpath $ipl::PropelIPLocal_path/interfaces
562	        }
563	
564	        set abstractionDefinition [ipl::getnode \
565	            {} abstractionDefinition_desc $if]
566	        set busDefinition [ipl::getnode {} busDefinition_desc $if]
567	
568	        set vendor [ipl::getncont busDefinition_desc ipxact:vendor $if]
569	        set library [ipl::getncont busDefinition_desc ipxact:library $if]
570	        set name [ipl::getncont busDefinition_desc ipxact:name $if]
571	        set version [ipl::getncont busDefinition_desc ipxact:version $if]
572	
573	        if {[file exist $dpath/$vendor/$library/$name/$version] != 1} {
574	            file mkdir $dpath/$vendor/$library/$name/$version
575	        }
576	
577	        set busdef \
578	            [open "$dpath/$vendor/$library/$name/$version/${name}.xml" w]
579	        puts $busdef {<?xml version="1.0" encoding="UTF-8"?>}
580	        puts $busdef [ipl::generate_xml $busDefinition]
581	        close $busdef
582	        set abstdef \
583	            [open "$dpath/$vendor/$library/$name/$version/${name}_rtl.xml" w]
584	        puts $abstdef {<?xml version="1.0" encoding="UTF-8"?>}
585	        puts $abstdef [ipl::generate_xml $abstractionDefinition]
586	        close $abstdef
587	    }
