602	    proc generate_xml {node {nid "0"} {index 0}} {
603	        set name [lindex $node 0]
604	        set attr [lindex $node 1]
605	        set content [lindex $node 2]
606	        set childs [lindex $node 3]
607	
608	        if {$name == ""} {
609	            set xmlstring ""
610	            foreach {id child} $childs {
611	                set xmlstring "$xmlstring[generate_xml $child $id $index]"
612	            }
613	        } else {
614	            set xmlstring "[string repeat "    " $index]<$name"
615	            if {$name == "lsccip:port" || $name == "lsccip:setting"} {
616	                set rep [expr [string length $name] + 1]
617	                foreach {id att} $attr {
618	                    set xmlstring "$xmlstring $att\n[string repeat "    " \
619	                        $index][string repeat " " $rep]"
620	                }
621	            } else {
622	                foreach {id att} $attr {
623	                    set xmlstring "$xmlstring $att"
624	                }
625	            }
626	            if {$content == "" && $childs == ""} {
627	                set xmlstring "$xmlstring/>\n"
628	            } elseif {$content != "" && $childs == ""} {
629	                set xmlstring "$xmlstring>$content</$name>\n"
630	            } else {
631	                set xmlstring "$xmlstring>$content\n"
632	                foreach {id child} $childs {
633	                    set xmlstring \
634	                        "$xmlstring[generate_xml $child $id [expr $index + 1]]"
635	                }
636	                set xmlstring \
637	                    "$xmlstring[string repeat "    " $index]</$name>\n"
638	            }
639	        }
640	        return $xmlstring
641	    }
