643	    proc setnode {path id node {desc {"" "" "" ""}}} {
644	        set debug 0
645	        set childs [lindex $desc 3]
646	        set pth [string map {/ " "} $path]
647	        set pth0 [lindex $pth 0]
648	        set pt [string map {" " /} [lrange $pth 1 end]]
649	        if {$debug} {
650	            puts "pth: $pth"
651	            puts "pth0: $pth0"
652	            puts "pt: $pt"
653	        }
654	        if {[llength $pth] != 0 } {
655	            if {$debug} {
656	                puts "dict keys childs pth0: [dict keys $childs $pth0]"
657	                puts "childs: $childs"
658	            }
659	            if {[dict keys $childs $pth0] != ""} {
660	                if {$debug} {
661	                    puts "childs(pth0): [dict get $childs $pth0]"
662	                }
663	                dict set childs $pth0 \
664	                    [setnode $pt $id $node [dict get $childs $pth0]]
665	                lset desc 3 $childs
666	                if {$debug} {
667	                    puts "childs: $childs"
668	                }
669	            } else {
670	                puts {ERROR: Wrong path, please check the path in the \
671	                setnode {path id node {desc {}}} process!}
672	            }
673	        } else {
674	            dict set childs $id $node
675	            lset desc 3 $childs
676	        }
677	        return $desc
678	    }
