680	    proc getnode {path id desc} {
681	        set childs [lindex $desc 3]
682	        set pth [string map {/ " "} $path]
683	        set pth0 [lindex $pth 0]
684	        set pt [string map {" " /} [lrange $pth 1 end]]
685	
686	        if {[llength $pth] != 0 } {
687	            if {[dict keys $childs $pth0] != ""} {
688	                return [getnode $pt $id [dict get $childs $pth0]]
689	            } else {
690	                puts {ERROR: Wrong path, please check the path in the \
691	                getnode {path id node {desc {}}} process!}
692	                exit 2
693	            }
694	        } else {
695	            if {[dict keys $childs $id] != ""} {
696	                return [dict get $childs $id]
697	            }
698	        }
699	    }
