701	    proc rmnode {path id desc} {
702	        set childs [lindex $desc 3]
703	        set pth [string map {/ " "} $path]
704	        set pth0 [lindex $pth 0]
705	        set pt [string map {" " /} [lrange $pth 1 end]]
706	
707	        if {[llength $pth] != 0 } {
708	            if {[dict keys $childs $pth0] != ""} {
709	                dict set childs $pth0 [rmnode $pt $id [dict get $childs $pth0]]
710	                lset desc 3 $childs
711	            } else {
712	                puts {ERROR: Wrong path, please check the path in the \
713	                rmnode {path id node {desc {}}} process!}
714	                exit 2
715	            }
716	        } else {
717	            if {[dict keys $childs $id] != ""} {
718	                dict unset childs $id
719	                lset desc 3 $childs
720	            } else {
721	                puts "rmnode:"
722	                puts "WARNING, no element with id:$id found!"
723	            }
724	        }
