728	    proc getnchilds {path id desc} {
729	        set childs [lindex $desc 3]
730	        set pth [string map {/ " "} $path]
731	        set pth0 [lindex $pth 0]
732	        set pt [string map {" " /} [lrange $pth 1 end]]
733	
734	        if {[llength $pth] != 0 } {
735	            if {[dict keys $childs $pth0] != ""} {
736	                return [getnchilds $pt $id [dict get $childs $pth0]]
737	            } else {
738	                puts {ERROR: Wrong path, please check the path in the \
739	                getnode {path id node {desc {}}} process!}
740	                exit 2
741	            }
742	        } else {
743	            if {[dict keys $childs $id] != ""} {
744	                set node [dict get $childs $id]
745	                return [lindex $node 3]
746	            }
747	        }
748	    }
749	
750	    proc rmnchilds {path id desc} {
751	        set childs [lindex $desc 3]
752	        set pth [string map {/ " "} $path]
753	        set pth0 [lindex $pth 0]
754	        set pt [string map {" " /} [lrange $pth 1 end]]
755	
756	        if {[llength $pth] != 0 } {
757	            if {[dict keys $childs $pth0] != ""} {
758	                dict set childs $pth0 \
759	                    [rmnchilds $pt $id [dict get $childs $pth0]]
760	                lset desc 3 $childs
761	            } else {
762	                puts {ERROR: Wrong path, please check the path in the \
763	                rmnode {path id node {desc {}}} process!}
764	                exit 2
765	            }
766	        } else {
767	            if {[dict keys $childs $id] != ""} {
768	                set node [dict get $childs $id]
769	                lset node 3 {}
770	                dict set childs $id $node
771	                lset desc 3 $childs
772	            } else {
773	                puts "rmnchilds:"
774	                puts "WARNING, no element with id:$id found!"
775	            }
776	        }
777	        return $desc
778	    }
