845	## Sets the IP structure with the specified general IP parameters.
846	## You can check the Lattice Propel IP Packager documentation for parameter
847	## use cases at: https://www.latticesemi.com/view_document?document_id=54003
848	#
849	## Quick usage: 'set ip [ipl::general -ip $ip <options>]'
850	#
851	# \opt[ip] -ip $ip
852	# \opt[vlnv] -vlnv {analog.com:<lib_name>:<ip_name>:<ip_version>}
853	# \opt[display_name] -display_name "AXI_DMA ADI"
854	# \opt[category] -category "DATA_TRANSFER"
855	# \opt[keywords] -keywords "<some descriptive words>"
856	# \opt[min_radiant_version] -min_radiant_version 2022.1
857	# \opt[max_radiant_version] -max_radiant_version 2023.2
858	# \opt[min_esi_version] -min_esi_version 2022.1
859	# \opt[max_esi_version] -max_esi_version 2023.2
860	# \opt[supported_products] -supported_products {LIFCL LFD2NX LFCPNX}
861	#                          -supported_products {*} #<this means all devices>#
862	# \opt[supported_platforms] -supported_platforms {esi radiant}
863	# \opt[href] -href "https://analogdevicesinc.github.io/hdl/library/axi_dmac/index.html"
864	###############################################################################
865	    proc general {args} {
866	        array set opt [list -ip "$::ipl::ip" \
867	            -vlnv "" \
868	            -vendor "analog.com" \
869	            -library "ip" \
870	            -name "" \
871	            -display_name "" \
872	            -version "1.0" \
873	            -category "ADI" \
874	            -keywords "ADI IP" \
875	            -min_radiant_version "2022.1" \
876	            -max_radiant_version "" \
877	            -type "" \
878	            -min_esi_version "2022.1" \
879	            -max_esi_version "" \
880	            -supported_products "" \
881	            -supported_platforms "" \
882	            -href "" \
883	        {*}$args]
884	
885	        set vlnv $opt(-vlnv)
886	
887	        set vlnv [split $vlnv ":"]
888	        set ll [llength $vlnv]
889	        if {$ll == 4} {
890	            set opt(-vendor) [lindex $vlnv 0]
891	            set opt(-library) [lindex $vlnv 1]
892	            set opt(-name) [lindex $vlnv 2]
893	            set opt(-version) [lindex $vlnv 3]
894	        } else {
895	            puts {WARNING: vlnv is not correct!}
896	        }
897	
898	        set optl {
899	            vendor
900	            library
901	            name
902	            display_name
903	            version
904	            category
905	            keywords
906	            min_radiant_version
907	            max_radiant_version
908	            type
909	            min_esi_version
910	            max_esi_version
911	        }
912	        set ip $opt(-ip)
913	        set href $opt(-href)
914	        set supported_products $opt(-supported_products)
915	        set supported_platforms $opt(-supported_platforms)
916	
917	        if {$href != ""} {
918	            set ip [ipl::setncont ip_desc/lsccip:general href $href $ip]
919	        }
920	
921	        foreach op $optl {
922	            set val $opt(-$op)
923	            if {$val != ""} {
924	                set gtnm [ipl::getnname ip_desc/lsccip:general "lsccip:$op" $ip]
925	                if {$gtnm != ""} {
926	                    set ip [ipl::setncont \
927	                        ip_desc/lsccip:general "lsccip:$op" $val $ip]
928	                } else {
929	                    set ip [ipl::setnode \
930	                        ip_desc/lsccip:general "lsccip:$op" \
931	                        [list "lsccip:$op" {} $val {}] $ip]
932	                }
933	            }
934	        }
935	        foreach family $supported_products {
936	            set sfamily [list lsccip:supported_family \
937	                [list name "name=\"$family\""] {} {}]
938	            set ip [ipl::setnode \
939	                ip_desc/lsccip:general/lsccip:supported_products \
940	                $family $sfamily $ip]
941	        }
942	        foreach platform $supported_platforms {
943	            set splatform [list lsccip:supported_platform \
944	                [list name "name=\"$platform\""] {} {}]
945	            set ip [ipl::setnode \
946	                ip_desc/lsccip:general/lsccip:supported_platforms \
947	                $platform $splatform $ip]
948	        }
949	        return $ip
950	    }
