1205	        array set opt [list -mod_data "" \
1206	            -v_prefix "" \
1207	            -xptn_portlist "" \
1208	            -regexp "" \
1209	        {*}$args]
1210	
1211	        set mod_data $opt(-mod_data)
1212	        set v_prefix $opt(-v_prefix)
1213	        set xptn_portlist $opt(-xptn_portlist)
1214	        set regexp $opt(-regexp)
1215	        set ports [dict get $mod_data portlist]
1216	
1217	        set portlist {}
1218	        set regx [list ${v_prefix}_.+]
1219	        if {$regexp != ""} {
1220	            set regx $regexp
1221	        }
1222	        foreach line $ports {
1223	            set pname [dict get $line name]
1224	            set existpn [lsearch $xptn_portlist $pname]
1225	            if {$existpn == -1 && [regexp $regx $pname]} {
1226	                set portlist [list {*}$portlist $pname]
1227	            }
1228	        }
1229	        return $portlist
1230	    }
