1467	            set ip_name [ipl::getncont ip_desc/lsccip:general lsccip:name $ip]
1468	        }
1469	        if {$ip_name == ""} {
1470	            puts "ERROR: You must define ip_name or '-name' at ipl::general!"
1471	            exit 2
1472	        }
1473	        if {$dpath == ""} {
1474	            set dpath $ipl::PropelIPLocal_path
1475	        }
1476	        if {[file exist $dpath] != 1} {
1477	            file mkdir $dpath
1478	        }
1479	        if {[file exist $dpath/$ip_name/doc] != 1} {
1480	            file mkdir $dpath/$ip_name/doc
1481	        }
1482	        set file [open "$dpath/$ip_name/doc/introduction.html" w]
1483	        foreach line [ipl::docsgen $ip] {
1484	            puts $file $line
1485	        }
1486	        close $file
1487	        set fdeps [ipl::getnchilds {} fdeps $ip]
1488	        foreach {folder flist} $fdeps {
1489	            if {$flist != ""} {
1490	                if {[file exists $dpath/$ip_name/$folder] != 1} {
1491	                    file mkdir $dpath/$ip_name/$folder
1492	                }
1493	                file copy -force {*}$flist $dpath/$ip_name/$folder
