1495	        }
1496	
1497	        set busInterfaces_desc [ipl::getnode {} busInterfaces_desc $ip]
1498	        if {$busInterfaces_desc != ""} {
1499	            set ip [ipl::include -ip $ip -include bus_interface.xml]
1500	            set file [open "$dpath/$ip_name/bus_interface.xml" w]
1501	            puts [generate_xml $busInterfaces_desc]
1502	            puts $file [generate_xml $busInterfaces_desc]
1503	            close $file
1504	        } else {
1505	            puts "WARNING, No busInterfaces_desc defined!"
1506	        }
1507	        set addressSpaces_desc [ipl::getnode {} addressSpaces_desc $ip]
