1538	###############################################################################
1539	## Parses a modules data into a specified structure, this structure then can
1540	## be used in other procedures which simplify the IP generation.
1541	## Quick usage: 'set mod_data [ipl::parse_module ./axi_dmac.v]'
1542	#
1543	# \parameter[path] ./axi_dmac.v
1544	###############################################################################
1545	    proc parse_module {path} {
1546	        set debug 0
1547	        set file [open $path]
1548	        set data [read $file]
1549	        close $file
1550	
1551	        set index [string first "\n" $data]
1552	
1553	        if {$index == -1} {
1554	            set first_line $data
1555	        } else {
1556	            set first_line [string range $data 0 $index]
1557	        }
1558	
1559	        if {[regexp {\s*module\s+[^;#(\n]+} $first_line match]} {
1560	            set mod_name [string map {" " ""} [lindex $match 1]]
1561	        } elseif {[regexp {\n\s*module\s+[^;#(\n]+} $data match]} {
1562	            set mod_name [string map {" " ""} [lindex $match 1]]
1563	        } else {
1564	            puts {ERROR, no module found in the verilog file!}
1565	            exit 2
1566	        }
1567	
1568	        set portlist {}
1569	        set parlist {}
1570	
1571	        set param_lines [regexp -all -inline {\n\s*parameter[^\n]+} $data]
1572	        set last_param_line [lindex $param_lines end]
1573	        set param_lines [lrange $param_lines 0 end-1]
1574	
1575	        set port_lines [regexp -all -inline \
1576	            {\n\s*input[^\n]+|\n\s*output[^\n]+|\n\s*inout[^\n]+} $data]
1577	
1578	        # to match {dir, type, size, name}
1579	        set regx_port \
1580	            {\s*(input|output|inout)\s+(\w+\s+)?(\[.+:.+\]\s+)?(\w+)\s*}
1581	        # to match {type, size, name, sign, value}
1582	        set regx_param \
1583	            {\s*parameter\s+(\w+\s+)?(\[.+:.+\]\s+)?(\w+)\s*(=\s*)?([^,;]+)?\s*}
1584	
1585	        foreach line $port_lines {
1586	            set captures [split $line {,;}]
1587	            foreach cap $captures {
1588	                if {$cap != ""} {
1589	                    if {[regexp $regx_port $cap -> direction type size name]} {
1590	                        set portlist [list {*}$portlist \
1591	                            [ipl::format_port $direction $type $size $name]]
1592	                    }
1593	                }
1594	            }
1595	        }
1596	
1597	        foreach line $param_lines {
1598	            set captures [split $line {,;}]
1599	            foreach cap $captures {
1600	                if {$cap != ""} {
1601	                    if {[regexp $regx_param $cap -> type size name sign value]} {
1602	                        set parlist [list {*}$parlist \
1603	                            [ipl::format_parameter $type $size $name $value]]
1604	                    }
1605	                }
1606	            }
1607	        }
1608	        set captures [split $last_param_line {,;}]
1609	        foreach cap $captures {
1610	            if {$cap != ""} {
1611	                if {[regexp $regx_param $cap -> type size name sign value]} {
1612	                    if {[regexp {(|)} $value]} {
1613	                        set value [ipl::get_balanced_section $value]
1614	                    }
1615	                    set parlist [list {*}$parlist \
1616	                        [ipl::format_parameter $type $size $name $value]]
1617	                }
1618	            }
1619	        }
1620	
1621	        set mod_data [list portlist $portlist parlist $parlist \
1622	            mod_name $mod_name]
1623	        return $mod_data
1624	    }
1625	
1626	    proc get_balanced_section {str {open {(}} {close {)}}} {
1627	        set diff 0
1628	        set last_index 0
1629	
1630	        for {set i 0} {$i < [string length $str]} {incr i} {
1631	            set char [string index $str $i]
1632	            if {$char == $open} {
1633	                incr diff
1634	            } elseif {$char == $close} {
1635	                if {$diff == 0} {
1636	                    set last_index $i
1637	                    break
1638	                }
1639	                incr diff -1
1640	            }
1641	            if {$diff == 0} {
1642	                set last_index [expr {$i + 1}]
1643	            }
1644	        }
1645	        return [string range $str 0 [expr {$last_index - 1}]]
1646	    }
