1648	    proc format_parameter {type size name value} {
1649	        if {$type != ""} {
1650	            set type [string map {" " ""} $type]
1651	            dict set param type $type
1652	        }
1653	        if {$size != ""} {
1654	            set size [string map {"[" "" "]" "" " " ""} $size]
1655	            set size [split $size {:}]
1656	            set from [lindex $size 0]
1657	            set to [lindex $size 1]
1658	            dict set param from $from
1659	            dict set param to $to
1660	        }
1661	        dict set param name $name
1662	        if {$value != ""} {
1663	            set value [string map {" " ""} $value]
1664	            dict set param value $value
1665	        }
1666	        return $param
1667	    }
