1669	    proc format_port {direction type size name} {
1670	        dict set port dir $direction
1671	        if {$type != ""} {
1672	            set type [string map {" " ""} $type]
1673	            dict set port type $type
1674	        }
1675	        if {$size != ""} {
1676	            set size [string map {"[" "" "]" "" " " ""} $size]
1677	            set size [split $size {:}]
1678	            set from [lindex $size 0]
1679	            set to [lindex $size 1]
1680	            dict set port from $from
1681	            dict set port to $to
1682	        }
1683	        dict set port name $name
1684	        return $port
1685	    }
