1687	###############################################################################
1688	## Adds a predefined interface to the IP structure.
1689	## Creates memory map or address space by default if there is no memory map
1690	## or address space added to the IP if the address space or memory map
1691	## refference is specified. The address space is created for the full range of
1692	## 32 bit address. The default memory map range is 64k. If you want to specify
1693	## separately you can add them manually then use the memory map or address space
1694	## name at -mem_map_ref -addr_space_ref. you can even update later using the
1695	## reference name specified here by using: ipl::add_memory_map or
1696	## ipl::add_address_space. As summary you must specify -mem_map_ref or
1697	## -addr_space_ref depending on slave or master whenever you add a memory mapped
1698	## interface to the IP.
1699	#
1700	# \opt[ip] -ip $ip
1701	# \opt[inst_name] -inst_name fifo_wr
1702	# \opt[display_name] -display_name fifo_wr
1703	# \opt[description] -description fifo_wr
1704	# \opt[master_slave] -master_slave slave
1705	# \opt[portmap] -portmap {{"fifo_rd_en" "EN"} {"fifo_rd_dout" "DATA"}}
1706	# \opt[mem_map_ref] -mem_map_ref s_axi_mem_map
1707	# \opt[addr_space_ref] -addr_space_ref m_axi_aspace_ref
1708	# \opt[vlnv] -vlnv {analog.com:<lib_name>:<interface_name>:<interface_version>}
1709	###############################################################################
1710	    proc add_interface {args} {
1711	        array set opt [list -ip "$::ipl::ip" \
1712	            -vlnv "" \
1713	            -inst_name "" \
1714	            -display_name "" \
1715	            -description "" \
1716	            -master_slave "" \
1717	            -mem_map_ref "" \
1718	            -addr_space_ref "" \
1719	            -portmap "" \
1720	        {*}$args]
1721	
1722	        set c {"}
1723	        set vlnv $opt(-vlnv)
1724	        set ip $opt(-ip)
1725	        set inst_name $opt(-inst_name)
1726	        set display_name $opt(-display_name)
1727	        set description $opt(-description)
1728	        set master_slave $opt(-master_slave)
1729	        set mem_map_ref $opt(-mem_map_ref)
1730	        set addr_space_ref $opt(-addr_space_ref)
1731	        set portmap $opt(-portmap)
1732	
1733	        set vlnv [split $vlnv ":"]
1734	        set ll [llength $vlnv]
1735	        if {$ll == 4} {
1736	            set vendor [lindex $vlnv 0]
1737	            set library [lindex $vlnv 1]
1738	            set name [lindex $vlnv 2]
1739	            set version [lindex $vlnv 3]
1740	        } else {
1741	            puts {WARNING: vlnv is not correct!}
1742	        }
1743	
1744	        if {$master_slave == "slave" && $mem_map_ref != ""} {
1745	            if {[ipl::getnode memoryMaps_desc $mem_map_ref $ip] == ""} {
1746	                set ip [ipl::add_memory_map -ip $ip \
1747	                    -name $mem_map_ref \
1748	                    -description $mem_map_ref \
1749	                    -baseAddress 0 \
1750	                    -range 65536 \
1751	                    -width 32]
1752	            }
1753	        }
1754	        if {$master_slave == "master" && $addr_space_ref != ""} {
1755	            if {[ipl::getnode addressSpaces_desc $addr_space_ref $ip] == ""} {
1756	                set ip [ipl::add_address_space -ip $ip \
1757	                    -name $addr_space_ref \
1758	                    -range 0x100000000 \
1759	                    -width 32]
1760	            }
1761	        }
1762	
1763	        set atts [list library "library=\"$library\"" \
1764	            name "name=\"$name\"" \
1765	            vendor "vendor=\"$vendor\"" \
1766	            version "version=\"$version\""]
1767	
1768	        set bif $::ipl::busInterface_desc
1769	        set bif [ipl::setncont {} lsccip:name $inst_name $bif]
1770	        set bif [ipl::setncont {} lsccip:displayName $display_name $bif]
1771	        set bif [ipl::setncont {} lsccip:description $description $bif]
1772	        set bif [ipl::setatts {} lsccip:busType $atts $bif]
1773	        dict set atts name "name=\"${name}_rtl\""
1774	        set bif [ipl::setatts lsccip:abstractionTypes/lsccip:abstractionType \
1775	            lsccip:abstractionRef $atts $bif]
1776	        set bif [ipl::setnname {} lsccip:master_slave lsccip:$master_slave $bif]
1777	
1778	        if {$master_slave == "slave" && $mem_map_ref != ""} {
1779	            set mmap_ref_node [list lsccip:memoryMapRef \
1780	                [list memoryMapRef "memoryMapRef=\"$mem_map_ref\""] {} {}]
1781	            set bif [ipl::setnode \
1782	                lsccip:master_slave lsccip:memoryMapRef $mmap_ref_node $bif]
1783	        }
1784	        if {$master_slave == "master" && $addr_space_ref != ""} {
1785	            set aspace_ref_node [list lsccip:addressSpaceRef \
1786	                [list addressSpaceRef "addressSpaceRef=\"$addr_space_ref\""] \
1787	                {} {}]
1788	            set bif [ipl::setnode lsccip:master_slave lsccip:addressSpaceRef \
1789	                $aspace_ref_node $bif]
1790	        }
1791	
1792	        foreach line $portmap {
1793	            set pname [lindex $line 0]
1794	            set logic [lindex $line 1]
1795	            set pmap [ipl::setncont \
1796	                lsccip:logicalPort lsccip:name $logic $::ipl::portMap_desc]
1797	            set pmap [ipl::setncont \
1798	                lsccip:physicalPort lsccip:name $pname $pmap]
1799	            set bif [ipl::setnode \
1800	                lsccip:abstractionTypes/lsccip:abstractionType/lsccip:portMaps \
1801	                $pname $pmap $bif]
1802	            set ip [ipl::set_port \
1803	                -ip $ip \
1804	                -name $pname \
1805	                -bus_interface $inst_name]
1806	        }
1807	        set bifs [ipl::getnode {} busInterfaces_desc $ip]
1808	        if {$bifs == ""} {
1809	            set bifs $::ipl::busInterfaces_desc
1810	        }
1811	        set bifsl [lindex $bifs 3]
1812	        dict set bifsl $inst_name $bif
1813	        lset bifs 3 $bifsl
1814	        set ip [ipl::setnode {} busInterfaces_desc $bifs $ip]
1815	
1816	        return $ip
1817	    }
