1958	###############################################################################
1959	## Sets the IP structure with parameters' data from top module.
1960	## This is only recomended if you have few parameters in top module but you
1961	## don't care the ordering and grouping of them. You can additionally edit the
1962	## GUI appearance of a parameter by using ipl_set_parameter but not the
1963	## ordering and grouping of them.
1964	## Quick usage: 'set mod_data [ipl::parse_module ./axi_dmac.v]'
1965	#               'set ip $::ipl::ip'
1966	#               'set ip [ipl::add_parameters_from_module -ip $ip -mod_data $mod_data]'
1967	#
1968	# \opt[ip] -ip $ip
1969	# \opt[mod_data] -mod_data $mod_data
1970	###############################################################################
1971	    proc add_parameters_from_module {args} {
1972	        array set opt [list -ip "$::ipl::ip" \
1973	            -mod_data "" \
1974	        {*}$args]
1975	        set ip $opt(-ip)
1976	        set mod_data $opt(-mod_data)
1977	
1978	        set mod_name [dict get $mod_data mod_name]
1979	        foreach data [dict get $mod_data parlist] {
1980	            set name [dict get $data name]
1981	
1982	            set value ""
1983	            if {[dict keys $data value] != ""} {
1984	                set value [dict get $data value]
1985	            }
1986	            if {$value != ""} {
1987	                set value [dict get $data value]
1988	                set regxf {^\s*-?[0-9]*\.[0-9]+\s*$}
1989	                set regxi {^\s*-?[0-9]+\s*$}
1990	                set regxstr {^\".*\"$}
1991	                if {[regexp $regxf $value]} {
1992	                    set value_type float
1993	                } elseif {[regexp $regxi $value]} {
1994	                    set value_type int
1995	                } elseif {[regexp $regxstr $value]} {
1996	                    set value_type string
1997	                }
1998	
1999	                set ip [ipl::set_parameter -ip $ip -id $name \
2000	                    -type param -value_type $value_type \
2001	                    -conn_mod $mod_name -title $name \
2002	                    -default $value \
2003	                    -output_formatter nostr \
2004	                    -group1 PARAMS -group2 GLOB]
2005	            } else {
2006	                set ip [ipl::set_parameter -ip $ip -id $name \
2007	                    -type param -value_type int \
2008	                    -conn_mod $mod_name -title $name \
2009	                    -output_formatter nostr \
2010	                    -group1 PARAMS \
2011	                    -group2 GLOB]
2012	            }
2013	        }
2014	        return $ip
2015	    }
